import{z as A,x as p,o,c as W,q as l,j as r,D as e,d as n,s,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"LWW 与冲突","description":"","frontmatter":{"title":"LWW 与冲突","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lww-conflict.md","filePath":"cs/lww-conflict.md","lastUpdated":1791413859000}'),B={name:"cs/lww-conflict.md"};function d(m,a,C,L,c,h){const E=p("Mermaid");return o(),W("div",null,[a[2]||(a[2]=l('<h1 id="lww-与冲突" tabindex="-1">LWW 与冲突 <a class="header-anchor" href="#lww-与冲突" aria-label="Permalink to &quot;LWW 与冲突&quot;">​</a></h1><div class="epigraph"><p>Last-Writer-Wins 用时间戳全序强行打结。并发写里有一侧被丢，收敛很快，语义可能错。</p><footer>—— 据 DeCandia et al., Dynamo, SOSP 2007；Johnson and Thomas, RFC 677, 1975 的时间戳副本整理</footer></div><p>上一课<a href="/cs/dynamo-anti-entropy">Dynamo</a>用向量时钟<strong>检出</strong>并发。缺口是<strong>打结</strong>：检出之后系统必须给出一个值。最便宜的规则是比较时间戳，大者赢。本课说明它丢什么，不把 CRDT 的交换幂等提前当解药全文。后课 CRDT 从「不要丢」再起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两写不可比（向量不可比），但存储只要一个 blob。LWW：取墙钟或 HLC 或 Lamport 标量较大者，删另一份。收敛：是，所有副本终见同一时间戳。正确：若两次写是「购物车加不同商品」，丢掉一侧等于丢商品。若写是覆盖型配置，后写覆盖可能正是意图——但「后」在并发下是假的，只是钟大。</p><p>Johnson–Thomas 已用时间戳副本。Dynamo 论文明确让应用合并购物车，而不是默默 LWW。许多数据库默认 LWW 是因为实现十行。</p><p><span class="marginnote">墙钟 LWW 在 \\(\\varepsilon\\) 内是随机丢。HLC 尊重因果：\\(a\\to b\\) 则 \\(b\\) 赢；并发仍按 \\(l,c\\) 假全序丢一边。</span></p><p><span class="marginnote">直觉类比：两个客服同时改同一份订单，各自盖自己腕表的时间。谁的表走得快谁的版本赢——和谁「动手晚」毫无关系。两块表差 50 毫秒，并发写的胜负就基本是掷硬币，输的那份被静默销毁。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>策略分层：能比因果则因果后继覆盖前驱；仅并发才进入冲突处理。处理菜单：LWW、保留多版本交应用、自动合并函数。选 LWW 必须声明「值是可覆盖标量，丢并发写可接受」。</p>',10)),(o(),r(i,null,{default:e(()=>[s(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20VV%5B%22%E7%89%88%E6%9C%AC%E5%90%91%E9%87%8F%22%5D%20--%3E%20CMP%7B%22%E5%8F%AF%E6%AF%94%3F%22%7D%0A%20%20CMP%20--%3E%7C%22a%E2%86%92b%22%7C%20KEEP%5B%22%E7%95%99%20b%22%5D%0A%20%20CMP%20--%3E%7C%22%E5%B9%B6%E5%8F%91%22%7C%20POL%5B%22LWW%20%2F%20%E5%BA%94%E7%94%A8%20%2F%20CRDT%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"读修复与反熵必须使用同一比较器，否则一边 LWW 一边保留多版本，会振荡。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[n("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"丢失更新：两个计数器 +1 变成 +1。这与单机丢失更新同构，只是用钟当锁。要计数应对 CRDT 或进共识。LWW 对「最后配置赢」类对象：仍可能把管理员的写丢掉，若另一副本钟快。运维看到的「数据丢了」常常是 LWW 而不是磁盘。",-1)),(o(),r(i,null,{default:e(()=>[s(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%89%AF%E6%9C%AC%20A%20%E6%94%B6%E5%88%B0%20%2B1%2C%20%E7%9B%96%E9%92%9F%2010%3A00%3A05%22%5D%20--%3E%20C%5B%22%E4%B8%A4%E5%86%99%E5%B9%B6%E5%8F%91%3A%20%E7%89%88%E6%9C%AC%E5%90%91%E9%87%8F%E4%B8%8D%E5%8F%AF%E6%AF%94%22%5D%0A%20%20B%5B%22%E5%89%AF%E6%9C%AC%20B%20%E6%94%B6%E5%88%B0%20%2B1%2C%20%E7%9B%96%E9%92%9F%2010%3A00%3A07%20%E5%81%8F%E5%BF%AB%22%5D%20--%3E%20C%0A%20%20C%20--%3E%20CMP%5B%22LWW%20%E6%AF%94%E8%BE%83%E5%99%A8%E5%8F%96%E6%97%B6%E9%97%B4%E6%88%B3%E5%A4%A7%E8%80%85%22%5D%0A%20%20CMP%20--%3E%20WIN%5B%22B%20%E7%9A%84%E5%80%BC%E8%83%9C%E5%87%BA%3A%20%E8%AE%A1%E6%95%B0%E4%B8%BA%203%22%5D%0A%20%20CMP%20--%3E%20DROP%5B%22A%20%E7%9A%84%E5%86%99%E8%A2%AB%E9%9D%99%E9%BB%98%E5%88%A0%E9%99%A4%22%5D%0A%20%20WIN%20--%3E%20LOST%5B%22%E4%B8%A4%E6%AC%A1%20%2B1%20%E5%8F%AA%E5%89%A9%E4%B8%80%E6%AC%A1%3A%20%E4%B8%A2%E5%A4%B1%E6%9B%B4%E6%96%B0%22%5D%0A%20%20DROP%20--%3E%20LOST%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">数字实例：购物车初值 2 件，两副本并发各 +1。LWW 只留钟大的副本，结果 3 件而非 4 件——时间戳比较丢掉的是整条写，不是把两次增量加起来。凡「要累加」的语义（计数、点赞数）都不能交给 LWW。</span></p><p>与<a href="/cs/linearizability">线性一致</a>：LWW 多主没有线性化点。与因果：LWW 用全序扩展消灭并发，看起来像顺序，其实是任意扩展，不是 Lamport 顺序一致（因为没有单一全局操作序被所有人同意事先，只是比较器事后）。</p><p>本课不把 Git merge 当 LWW：三路合并保留分叉。也不写限价簿成交价谁赢。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给出半格定理，不写 JSON 自动 merge 的全部坑。后课默认：无声明的「自动冲突解决」按 LWW 理解并假定可丢更新；要保留并发意图用 CRDT 或应用合并。会话保证不修复 LWW 丢值。</p><p>打结规则是规格的一部分。只写「最终一致」而默默 LWW，是把安全藏进实现。</p><p><span class="marginnote">常见误区：初学者容易以为「最终一致」就等于「冲突会被合理解决」。LWW 只保证所有副本最终相同，不保证相同的那个值没丢东西；打结规则不写进接口文档，用户就无法知道自己哪次写会输。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LWW 用全序消并发，收敛且可能丢更新。</li><li>因果可比时应用后继覆盖；LWW 只该打真并发。</li><li>计数、集合并等意图不能靠 LWW。</li><li>出处：Dynamo, SOSP 2007；Johnson and Thomas 时间戳副本。</li></ul>',9))])}const T=A(B,[["render",d]]);export{f as __pageData,T as default};
